-- 485_ar_dish_descriptions_and_ingredients.sql
-- Arabic dish copy: 77 descriptions + 75 ingredient lists (MC f91194f7). Completes the
-- Arabic data set started in 484.
--
-- Dish NAMES are deliberately absent — never translated in any language (mig 473a, CEO).
--
-- ALLERGEN CLAUSES ARE SAFETY COPY. Every English "Contains …" clause is carried over
-- literally, in the same order, with nothing merged or dropped: يحتوي على + the same list.
-- This has gone wrong twice (mig 450 RU, mig 475 TH both had to restore clauses the printed
-- menu had silently lost), so the 15 descriptions and 3 ingredient lines that carry one are
-- listed in the verification query at the bottom of this file.
--
-- Terminology notes, for whoever reviews the Arabic:
--   يحتوي على        = contains
--   الغلوتين / الألبان / البيض / السمسم / المحاريات / القشريات / الأسماك / الصويا /
--   الخردل / المكسرات الشجرية / الفول السوداني / اللوز  = gluten / dairy / eggs / sesame /
--   shellfish / crustacean / fish / soy / mustard / tree nuts / peanuts / almonds
--   جمبري            = shrimp/prawn (chosen over روبيان for the widest pan-Arab reading)
--   Brand and producer names (Barada Chocolate, MCT, MSG) stay Latin on purpose.
--
-- CONTRACT-REVIEWED: data-only inserts into content_translations. No schema change, no
-- table/view/function touched, so vault/Database/Schema.md needs no edit.

BEGIN;

-- ---------------------------------------------------------------- descriptions (77)
WITH d(entity_key, txt) AS (VALUES
  ('bc53ace2-6493-4720-8eff-28d1ff1a78e7', 'جرعة نقية وممتلئة القوام من الإسبريسو المختص ممدودة بالماء الساخن — جسورة وناعمة وبلا سكر.'),
  ('6e3e3a59-0811-4ba6-ae39-81081a29ed07', 'جرعة غنية ومكثّفة من إسبريسو بونكافيه المختص — نقية وعطرية ومنعشة. دفعة الطاقة المثالية.'),
  ('8dd59adb-5fcb-4fbc-b517-4f14ddad1379', 'توقيعنا المنعش: جرعة مزدوجة من الإسبريسو المختص فوق عصير برتقال طازج وثلج، مع شريحة برتقال طازجة — مشرق وحمضي ومُحبَّب بشكل غير متوقع.'),
  ('4b29684a-ef77-4e6d-817a-8d3e842ddf0d', 'ماتشا يابانية مطحونة بالحجر فوق عصير برتقال طازج وثلج — مشرقة وحمضية وخالية من الألبان، مع دفعة طبيعية من مضادات الأكسدة.'),
  ('950c12ec-7bc4-415b-9cf3-bbb439604f23', 'إسبريسو مختص وحليب مبخّر حريري مع دفقة من شراب الكراميل — ناعم وحلو ومريح. حليب جوز الهند عند الطلب.'),
  ('7e81d459-6643-4fee-aa6d-041fc9432826', 'إسبريسو مختص ممزوج بحليب مبخّر حريري — ناعم وكريمي ومريح. حليب جوز الهند عند الطلب.'),
  ('03e2b578-5d15-40cc-8a8f-c8f3da6767e0', 'منعشنا المميّز: جرعة إسبريسو فوق التونك الفوّار والثلج — حلو مرّ وفوّار ومشرق بشكل مفاجئ.'),
  ('572ac056-ce1e-405f-a2e3-aa616658ff12', 'جرعة نقية وممتلئة القوام من الإسبريسو المختص ممدودة بالماء البارد فوق الثلج — جسورة وناعمة وبلا سكر.'),
  ('52e66a9b-657f-4836-be6f-83519af7d4f2', 'كابتشينو فوق الثلج — إسبريسو جسور وحليب بارد مُرغى، ناعم ومنعش. حليب جوز الهند عند الطلب.'),
  ('fbca6756-c411-4edd-92fd-a3ca844379fa', 'إسبريسو مختص فوق حليب بارد وثلج مع دفقة من شراب الكراميل — ناعم وحلو ومنعش. حليب جوز الهند عند الطلب.'),
  ('d3cc700d-a0e6-4297-b87d-89aba6af4348', 'إسبريسو مختص مبرّد يُسكب فوق حليب بارد وثلج — ناعم ولطيف ومنعش. حليب جوز الهند عند الطلب.'),
  ('7313b3ea-a9b8-428d-8044-57249f622818', 'إسبريسو مختص تحت سحابة كثيفة من رغوة الحليب المخملية — كلاسيكي ومتوازن ودافئ. حليب جوز الهند عند الطلب.'),
  ('56fe9db8-98fc-4733-8084-b4928ff32d76', 'سيخان من الجمبري المشوي على خبز مسطّح دافئ مع سلطة ملفوف بالزبادي والطحينة، يُقدَّم مع حمص الشمندر المحمّص ومخلل الخيار وصوص الطحينة — 45 غرامًا من البروتين وأخف طبق في قائمة البروتين. يمكن تبديل سلطة الملفوف أو الحمص بفتوش أو تبولة صغيرة، أو أرز، أو أرز بني، أو بطاطس مشوية، أو حنطة سوداء بدون أي رسوم. يحتوي على الغلوتين والحليب والسمسم والمحاريات.'),
  ('72b5c330-c7ed-4119-8cbd-46bc8fb8607a', 'نكهة غنية ومكثّفة من شوكولاتتنا الداكنة الفاخرة بنسبة 70%، مصنوعة لعشّاق الكاكاو الفاخر الحقيقيين.'),
  ('77db2ddd-3bc0-4871-ae3c-0939bb6bc007', 'تناغم مثالي بين الشوكولاتة الداكنة المخملية واللوز المحمّص المقرمش، في سيمفونية بديعة من النكهات والقوام.'),
  ('9adab671-a468-4017-a869-184a4a56dc43', 'تمر ولوز مقرمش وطحينة كريمية وبذور القرع وعبّاد الشمس، مغلّفة بشوكولاتة داكنة غنية 100%. وجبة خفيفة مغذّية بعد التمرين. نباتي صرف. يحتوي على الفول السوداني. مربّعان في كل علبة. من إنتاج Barada Chocolate، فوكيت. القيم الغذائية محسوبة من قائمة المكوّنات وليست مختبرية.'),
  ('f4968c35-898a-4857-801e-294df2604010', 'لحم بقري متبّل يتغذى على الأعشاب من الشوّاية على خبز التورتيلا، مع الحمص وبيواز البصل بالسماق والطماطم ودبس الرمان.'),
  ('cca36b1b-fd2c-481f-a4b4-c796158e8750', 'حمصنا الكلاسيكي مخلوطًا بالشمندر المحمّص الحلو — ترابي، وردي زاهي، وغني بالألياف.'),
  ('d56425f6-8124-468c-b8cb-9e59a8f3bb01', 'خليط متوازن من الشوفان والفول السوداني والعسل وجوز الهند واللوز، مغلّف بشوكولاتة داكنة غنية بنسبة 70%. طاقة طبيعية ممتدة قبل أي تمرين. مربّعان في كل علبة. من إنتاج Barada Chocolate، فوكيت. القيم الغذائية محسوبة من قائمة المكوّنات وليست مختبرية.'),
  ('93c2d26e-d80f-4a49-901c-c9eb42b5e9c1', 'ثلاث بيضات مهروسة فوق حمص حريري على خبز 19 حبة محمّص، مع بذور السمسم وزيت الزيتون والخيار والطماطم الطازجة — بيض وحمص معًا لـ 35 غرامًا من البروتين. يحتوي على الألبان والبيض والغلوتين والسمسم.'),
  ('8fa36dd9-a1fa-4a47-a9a5-94c1f1facc74', 'ثلاث بيضات مقلية على طريقتك على خبز 19 حبة محمّص مع الخيار والطماطم، وحرية الاختيار من بار الخضار — بسيط وسريع و30 غرامًا من البروتين. يحتوي على البيض والغلوتين والألبان.'),
  ('caf652ea-3fd0-43d0-81db-d29f2b46f31d', 'ثلاث بيضات مهروسة على خبز 19 حبة محمّص تحت طبقة سميكة من غواكامولي الأفوكادو بالليمون الأخضر والكزبرة، مع الخيار والطماطم — دهون جيدة و31 غرامًا من البروتين ولا حاجة لشيء آخر حتى الغداء. يحتوي على الألبان والبيض والغلوتين.'),
  ('7031fd55-f23c-457f-8187-3081a37af174', 'ثلاث بيضات مهروسة مع خليط ذائب من ثلاث أجبان على خبز 19 حبة محمّص، تُقدَّم مع الخيار والطماطم وزيت الزيتون — 41 غرامًا من البروتين وأكثر الأطباق راحةً في قائمة الفطور. يحتوي على الألبان والبيض والغلوتين.'),
  ('cafbae4c-c508-4847-bb4f-67d1a08d2ecb', 'راب القمح الكامل مفتوحًا ومسطّحًا تحت الموزاريلا والشيدر والجبن الكريمي الذائب، مع السمسم الأبيض والأسود — يُقدَّم مع الطماطم الكرزية والخيار والزيتون والنعناع.'),
  ('0aafc743-51d3-450b-9c0e-1512c1943947', 'صدر دجاج مشوي مع شرائح الأفوكادو والموزاريلا والشيدر الذائب، مطويًا في راب القمح الكامل مع خس آيسبرغ مقرمش — يُقدَّم مع كريمة الثوم والغواكامولي.'),
  ('90f521cf-4064-409a-84a5-abe47b3bc46c', 'خس آيسبرغ مقرمش وطماطم كرزية حلوة مع شيش طاووق الدجاج المشوي وصوص سيزر الكريمي وجبن البارميزان وقطع الخبز المحمّص بالأعشاب — نسخة أخف وغنية بالبروتين من الكلاسيكية.'),
  ('ebd4e335-cd23-4782-b4e8-970738ede64f', 'صدر دجاج مشوي مع الفلفل الحلو ثلاثي الألوان والبصل، مطويًا في راب القمح الكامل مع سلطة ملفوف بالزبادي والطحينة — يُقدَّم مع خردل العسل وبيكو دي غايو.'),
  ('d3a7fe21-e6d1-42b4-a59b-9ba6d5781464', 'شيش طاووق دجاج متبّل ومشوي مع سلطة ملفوف بالزبادي والطحينة والخس والحمص في راب الحبوب الكاملة، محمّص على الشوّاية. مخلل الخيار على الجانب.'),
  ('ae0e06cf-1520-4a3a-a742-f09e1f3ff074', 'سيخان من شيش طاووق الدجاج المشوي على خبز مسطّح دافئ مع البقدونس والبصل الأحمر بالسماق، يُقدَّم مع حمص حريري وطبق تبولة بالأعشاب وصوص الطحينة — 62 غرامًا من البروتين في طبق واحد. يمكن تبديل السلطة أو الحمص بفتوش أو تبولة صغيرة، أو أرز، أو أرز بني، أو بطاطس مشوية، أو حنطة سوداء بدون أي رسوم. يحتوي على الغلوتين والسمسم.'),
  ('891738bc-c91a-4bae-8389-ed34c1a62ca1', 'أفوكادو مخملي وحليب جوز الهند الكريمي مخلوطان مع الموز والكاكاو الخام ولمسة من التمر — متعة شوكولاتية غنية سرّها الدهون الجيدة والألياف. خالٍ من الألبان، بدون سكر مضاف.'),
  ('be3c43e3-9229-46ee-a2a5-00281018bffa', 'شوكولاتة داكنة غنية بنسبة 70% مع جوز هند حلو وكريمي. مصنوعة من كاكاو تايلندي وجوز هند تايلندي. مربّعان في كل علبة. من إنتاج Barada Chocolate، فوكيت. القيم الغذائية محسوبة من قائمة المكوّنات وليست مختبرية.'),
  ('77b252f7-9f59-4ea9-936a-441a3f9e810f', 'اصنعه بنفسك: اختر الأساس والفواكه والمعزِّزات لتحصل على السموذي المثالي، يُخلط طازجًا. وشاهد السعرات الحرارية تتغيّر مع كل اختيار.'),
  ('cac858b3-07c0-4a3a-bfd0-38c22cdf16c8', 'حبوب الحمص والطحينة مخلوطة حتى النعومة مع الليمون والثوم، ومخفّفة إلى صوص سائل — بطعم المكسرات، خفيف وكريمي بلا كريمة.'),
  ('26e29fa3-4d25-4c54-96d4-ca268199d4d4', 'بيض مخفوق مع الفلفل الحلو ثلاثي الألوان المشوي والبصل، مطويًا في راب القمح الكامل مع سلطة ملفوف بالزبادي والطحينة — يُقدَّم مع مايونيز زيت الزيتون وبيكو دي غايو.'),
  ('714cd97c-17ad-421d-9238-158f6028fb76', 'فلافل الحمص المخبوزة على الحمص، مطوية في راب القمح الكامل مع الطماطم والخيار والمخلل والفجل وخس الآيسبرغ، مع الطحينة والسماق — تُقدَّم مع الحمص والطحينة.'),
  ('c6146cac-6a05-41fb-a559-4cffdc5fc41b', 'كلاسيكية الحدائق الشامية — خس مقرمش وخيار وطماطم وفجل مع صوص السماق ومقرمشات البذور. طازجة وحامضة وعشبية.'),
  ('333c53bc-4b41-40d9-ab31-afdf9a0afbf3', 'جوافة ناضجة معصورة على البارد — عطرية واستوائية وغنية بفيتامين C. فاكهة 100%، بدون سكر مضاف.'),
  ('ae357b84-e402-46ff-b485-b97bbc7bd040', 'أناناس ناضج بحرارة الشمس معصور على البارد — مشرق وعصيري وحامض منعش. فاكهة 100%، بدون سكر مضاف.'),
  ('8654ec3e-89f6-4bff-a9ad-18f568b64d31', 'سيخان من كباب اللحم البقري المتبّل الذي يتغذى على الأعشاب على خبز مسطّح دافئ مع البقدونس والبصل الأحمر بالسماق، يُقدَّم مع حمص حريري وسلطة طماطم وخيار وصوص الطحينة — 58 غرامًا من البروتين في طبق واحد. يمكن تبديل السلطة أو الحمص بفتوش أو تبولة صغيرة، أو أرز، أو أرز بني، أو بطاطس مشوية، أو حنطة سوداء بدون أي رسوم. يحتوي على الغلوتين والخردل والسمسم.'),
  ('1a8c010c-5684-453c-9e02-b14df1020229', 'فلفل حلو ثلاثي الألوان وخيار مقرمش مع الزيتون الأسود وشرائح البصل الأحمر الصغير وقطعة سميكة من جبن الفيتا اليوناني — بساطة إيجية، بلا خس وبلا حشو. يحتوي على الألبان.'),
  ('260c3da2-2bf5-4fe1-8733-56d1572699a9', 'خليط استوائي مشرق من الموز والكيوي الحامض والسبانخ الورقية، مع نعناع طازج منعش — منعش وغني بالفيتامينات وحلو بشكل طبيعي. خالٍ من الألبان.'),
  ('7331d6e5-1ca1-4c8d-aa3f-8211d125aa8b', 'نقية وبسيطة ومُرضية بعمق. شوكولاتة الحليب عالية الكاكاو هذه تُبرز غنى الكاكاو الفاخر. ناعمة ومتوازنة ومصنوعة لمن يتذوّق البساطة المُتقنة.'),
  ('d1a0f372-4bc2-4348-9734-3c15e64187ec', 'زبادي يوناني مخفّف بالطحينة الخام والليمون والثوم، منقّط بالبقدونس — بارد وحامض وكثيف بما يكفي للتغطية.'),
  ('f9f49d47-455f-4605-9a84-c771ef27efdf', 'الكلاسيكي — حمص كريمي مخلوط بالطحينة والليمون والثوم، مع زيت زيتون بكر ممتاز. ناعم، بطعم المكسرات، ومُغذٍّ.'),
  ('20cd9627-93ff-4a46-a858-f8a1f3d85842', 'طبق حمص مبني للبروتين: كومة كبيرة من التبولة بالأعشاب والرمان فوق حمص ناعم، ومكعبات طاووق الدجاج بالتتبيلة الحمراء، وقرع مخبوز مُكرمل، ومخلل الخيار، وقطع خبز محمّص بالأعشاب.'),
  ('c6e455b9-3823-41b7-8d5f-1032c243ccfb', 'ماتشا يابانية مطحونة بالحجر تلتقي بجرعة إسبريسو فوق الثلج — ترابية وجسورة وغنية بمضادات الأكسدة ومنعشة في الوقت نفسه.'),
  ('02c51821-c9fb-4cad-9ae1-e53bfe78c68a', 'ماتشا يابانية بالطريقة الاحتفالية مخفوقة ومسكوبة فوق الثلج مع حليب بارد ولمسة من العسل — منعشة وناعمة ومنشّطة بهدوء. حليب جوز الهند عند الطلب.'),
  ('1de11c01-7213-4656-8852-4161cd2713ba', 'لحم غنم مشوي مع المشروم والبصل تحت الموزاريلا والشيدر الذائب، مطويًا في راب القمح الكامل — يُقدَّم مع مايونيز الكمأة وكريمة الثوم.'),
  ('b42dc655-60bc-434e-a82a-b9c09a7d589a', 'مانجو ناضجة بحرارة الشمس وفراولة عصيرية مخلوطتان مع الموز — فاكهة خالصة، حلوة بشكل طبيعي، بدون سكر مضاف. خالٍ من الألبان.'),
  ('122ee0c0-9ef7-4ba6-a1f3-be1279753359', 'منشّط أخضر من الماتشا اليابانية والموز الناضج والسبانخ الورقية، مخلوط بالزبادي وحليب اللوز حتى الكريمية. مع بذور الشيا ولمسة من العسل — غني بمضادات الأكسدة، حلو بخفة ومنعش بشكل طبيعي.'),
  ('49c0b597-5b07-47e3-a02a-319f82f2a072', 'ماتشا يابانية بالطريقة الاحتفالية مخفوقة في حليب مبخّر حريري — ناعمة وحلوة بنكهة عشبية ومنشّطة بهدوء. حليب جوز الهند عند الطلب.'),
  ('8055f4d5-33df-46f6-8b3e-833d6c9a4c2d', 'فراولة وبلوبيري وموز مخلوطة مع بذور الشيا — غنية بمضادات الأكسدة، كريمية ومُغذية. دفعة من التوت في كل رشفة.'),
  ('06ed764a-61e8-4d43-b1d9-68197a90bd55', 'شريحة سميكة واحدة من خبز متعدد الحبوب بطريقة الخمير الطبيعي، محمّصة عند الطلب.'),
  ('ef733500-ed0f-4709-9fd6-0aea5dace670', 'جوزة هند فتية كاملة، مقشّرة طازجة وتُقدَّم مع قشّة — ماء جوز هند نقي ومرطّب مع لبّ جيلي طري. بلا أي إضافات.'),
  ('a522262f-6bf4-42be-be53-68c87d5d7e35', 'جمبري مشوي على الحجر البركاني وأصابع سرطان البحر فوق الكينوا المطبوخة مع الواكامي المتبّل والذرة الحلوة والملفوف المقطّع المقرمش — أخف طبق في القائمة بـ 119 سعرة حرارية. يحتوي على القشريات والمحاريات والأسماك والغلوتين والسمسم والصويا.'),
  ('a7ad72aa-35cd-4ab5-bfb3-98df91e460c2', 'لمستنا الاستوائية: جرعة مزدوجة من الإسبريسو المختص فوق الباشن فروت الحامض والثلج، مُتوّجة بلبّ باشن فروت طازج — نابض بالحياة، حامض ومنعش.'),
  ('b6eb9c6f-7758-4243-9e60-dbdb1f983c70', 'ماتشا يابانية مطحونة بالحجر تُسكب فوق الباشن فروت الحامض والثلج — استوائية ونابضة ومنعشة، خالية من الألبان وغنية بمضادات الأكسدة.'),
  ('3ab54c25-5f13-474f-a06e-6441e6767735', 'مانجو عطرية وباشن فروت حامض — ثنائي استوائي نابض بالحياة، فاكهة خالصة وحلو بشكل طبيعي. خالٍ من الألبان.'),
  ('7c0b5a47-06bf-4991-8ac8-4bb89fab7ac7', 'خوخ لطيف ومشمش مخلوطان مع الموز والزبادي الكريمي واللوز — ناعم وحلو بخفة، بدون سكر مضاف.'),
  ('70edd2bc-96d6-4abf-9e5c-47dd278cbb35', 'بطلنا بعد التمرين: خوخ وموز مخلوطان مع بروتين واي والزبادي وزبدة الفول السوداني — غني بالبروتين، حلو بشكل طبيعي ومُشبع فعلًا.'),
  ('50caeb0d-a3e1-45fa-9d91-e24419dc658a', 'قرع مخبوز مُكرمل وشمندر محمّص حلو فوق خس آيسبرغ مقرمش مع جبن الفيتا الكريمي والجوز المحمّص والكرانبيري المجفّف — ترابي وزاهي كالجواهر وحلو بشكل طبيعي. يحتوي على الألبان والمكسرات الشجرية.'),
  ('56c313bf-e54f-4aad-93df-03452860d491', 'دجاج مشوي بالتتبيلة الحمراء فوق خضار مقرمشة مع الغواكامولي وصلصة المانجو وبيكو دي غايو والفاصولياء الحمراء والذرة الحلوة — مع هالابينو مخلّل للحرارة.'),
  ('af8da10b-1881-4162-959b-600b50c36bb2', 'جمبري مشوي فوق طبقة سميكة من الغواكامولي على خبز 19 حبة محمّص، مع بيكو دي غايو الطازج وصلصة المانجو، وعصرة من الليمون.'),
  ('d6dd78a9-395c-458d-96b7-3958ea227f79', 'ستة حبات من الجمبري المشوي فوق خس آيسبرغ مقرمش وطماطم كرزية حلوة، مع صوص سيزر الكريمي وجبن البارميزان وقطع الخبز المحمّص بالأعشاب — طازج وغني بالبروتين وسخي.'),
  ('2664efd3-20f0-461c-ba1b-1945a1051685', 'جمبري مشوي مع الفلفل الحلو ثلاثي الألوان والبصل، مطويًا في راب القمح الكامل مع سلطة ملفوف بالزبادي والطحينة — يُقدَّم مع صوص الدايناميت والغواكامولي.'),
  ('63f6827f-7864-4a7d-9fbb-a08c066e37f9', 'باذنجان مشوي على الفحم بنكهة دخانية ممزوج بالطحينة والزبادي والليمون الطازج والثوم — ريفي وغني وكريمي، يُحضَّر باليد في جرن حجري. يحتوي على الألبان والسمسم.'),
  ('e3c4c04c-6152-4095-b71f-773308cf70d7', 'تراوت السلمون المدخّن الحريري مع البيض والأفوكادو الكريمي والخس المقرمش، مع الخيار والبصل الأحمر والشبت الطازج — خفيف وأنيق وغني بالأوميغا.'),
  ('2b3fefda-a0e8-436d-951f-cc37f6c28f25', 'تراوت السلمون المدخّن البارد فوق الغواكامولي وجبن الماعز على خبز 19 حبة محمّص، مع الشبت وعصرة من الليمون.'),
  ('e1b03413-f015-42ca-91c1-7afcfb55643d', 'الكلاسيكي الخالد — فراولة حلوة وموز ناضج مخلوطان مع بذور الشيا. كريمي ومُغذٍّ ومحبوب في كل الأعمار.'),
  ('cb75a0e0-9ab1-496d-9b99-6c40d35c8c93', 'سلطة طازجة غنية بالأعشاب من البقدونس والكينوا مع الطماطم والرمان وصوص السماق — مشرقة ومنعشة وخالية من الغلوتين بشكل طبيعي.'),
  ('de8ad210-6f05-48df-b8a1-c4ce85177a2f', 'طحينة خام مخفوقة بخل التفاح حتى تتماسك، ثم تُخفّف بالماء إلى كريمة حريرية، مع الليمون وبذور السمسم.'),
  ('a8f700c8-cf45-457a-a5ef-188d4797c350', 'نودلز شيراتاكي الكونجاك ممزوجة بصوص الفول السوداني بالزنجبيل والثوم مع الملفوف المقطّع والفجل الأبيض والجزر، مع الفول السوداني المحمّص والكزبرة — نودلز بلا كربوهيدرات تحمل صوصًا غنيًا حقًا. يحتوي على الغلوتين والفول السوداني والسمسم والصويا.'),
  ('6369381e-3621-4c7b-9c22-a3d5a290ab10', 'توفو صلب مقرمش وحبوب الحمص فوق الكينوا مع القرع المُكرمل والأفوكادو وخس البلوط الأخضر — نباتي بالكامل وأفضل طبق من حيث القيمة في القائمة. يحتوي على السمسم والصويا.'),
  ('b8eb8c21-3c09-485a-a6ee-d91b28d098dc', 'تونة وسلمون بدرجة الساشيمي فوق أرز الجاسمين مع المانجو الناضجة والأفوكادو والواكامي المتبّل — أسخى طبق في القائمة والوحيد المبني على سمك نيء. يحتوي على الأسماك والسمسم والصويا.'),
  ('cee60ec0-1dc9-424f-914f-13b9ce4b8c07', 'تورتيلا طرية من الحبوب الكاملة، تُسخّن عند الطلب.'),
  ('3d3e91b1-3653-4d28-9e3a-a76ea7f0b37e', 'نصف زعتر ونصف جبن: راب قمح كامل واحد مفتوح ومسطّح، مخبوز بالزعتر وزيت الزيتون على جانب، والموزاريلا والشيدر على الجانب الآخر — يُقدَّم مع الطماطم الكرزية والخيار والزيتون والنعناع.'),
  ('6a0434f5-7fef-41fe-9639-c9793774b83b', 'راب القمح الكامل مفتوحًا ومسطّحًا ومخبوزًا بالزعتر وزيت الزيتون، مع السمسم الأبيض والأسود — يُقدَّم مع الطماطم الكرزية والخيار والزيتون والنعناع.')
)
INSERT INTO public.content_translations (entity, entity_key, field, lang, value, source_hash)
