INSERT INTO public.content_translations (entity, entity_key, field, lang, value, source_hash)
SELECT 'dish', i.entity_key, 'ingredients', 'ar', to_jsonb(i.txt),
       md5(public.fn_translation_source('dish', i.entity_key, 'ingredients'))
FROM i
WHERE public.fn_translation_source('dish', i.entity_key, 'ingredients') IS NOT NULL
ON CONFLICT (entity, entity_key, field, lang) DO UPDATE
  SET value = EXCLUDED.value, source_hash = EXCLUDED.source_hash, reviewed_at = NULL, reviewed_by = NULL;

/*
  Allergen guard. This is the check that mig 450 (RU) and mig 475 (TH) each failed: an
  English "Contains …" clause silently absent from the translation. Note translation is
  jsonb, so it needs #>> '{}' — a bare LIKE on it raises 42883.

  Both queries returned 0 rows when this migration was applied (2026-10-16).

  -- (a) every "Contains …" row carries the Arabic clause at all. 27 rows match the
  --     source pattern (18 dish rows + the 9 allergen tags from mig 484); all 27 pass.
  SELECT entity, entity_key, field, source_text
  FROM v_translation_worklist
  WHERE lang = 'ar'
    AND source_text ~* '\mcontains\M'
    AND (translation IS NULL OR (translation #>> '{}') NOT LIKE '%يحتوي على%');

  -- (b) stronger: no INDIVIDUAL allergen is dropped from a clause. Word-bounded on the
  --     English side on purpose — a plain ILIKE '%fish%' also fires on "shellfish" and
  --     reports a false omission on the 12 Grilled Shrimp Meal.
  WITH m(en, ar) AS (VALUES
    ('gluten','الغلوتين'),('dairy','الألبان'),('milk','الحليب'),('eggs','البيض'),
    ('sesame','السمسم'),('shellfish','المحاريات'),('crustacean','القشريات'),
    ('fish','الأسماك'),('soy','الصويا'),('mustard','الخردل'),
    ('tree nuts','المكسرات الشجرية'),('peanuts','الفول السوداني'),('almonds','اللوز')
  ), r AS (
    SELECT entity_key, field, translation #>> '{}' AS ar,
           substring(source_text FROM 'Contains(.*)$') AS en_clause
    FROM v_translation_worklist
    WHERE lang = 'ar' AND entity = 'dish' AND source_text ~* '\mcontains\M'
  )
  SELECT r.entity_key, r.field,
         (SELECT string_agg(m.en, ', ') FROM m
           WHERE r.en_clause ~* ('\m'||m.en||'\M') AND r.ar NOT LIKE '%'||m.ar||'%') AS missing_in_ar
  FROM r
  WHERE EXISTS (SELECT 1 FROM m
                 WHERE r.en_clause ~* ('\m'||m.en||'\M') AND r.ar NOT LIKE '%'||m.ar||'%');
*/

INSERT INTO migration_log (filename, applied_by, checksum, notes)
VALUES ('485_ar_dish_descriptions_and_ingredients.sql', 'claude-code', NULL,
  'AR: 77 dish descriptions + 75 ingredient lists — Arabic data complete except dish names, which stay English by policy (mig 473a). All English "Contains ..." allergen clauses (18 dish rows) carried over literally as يحتوي على, allergen-by-allergen (MC f91194f7)')
ON CONFLICT DO NOTHING;

COMMIT;
